mapper.select:
SELECT COUNT(*)
FROM t_info_lesson l
WHERE DATE(COALESCE(l.lsn_adjusted_date, l.schedual_date))
      BETWEEN #{startDate} AND #{endDate}
AND l.del_flg = 0
AND NOT (
    l.schedual_type = 1
    AND DATE(l.schedual_date) BETWEEN #{startDate} AND #{endDate}
    AND l.lsn_adjusted_date IS NULL
)
